/**
 * Bridge to the host's `bc-ask` command. The host runs one read-only fork
 * subagent: it inherits the parent's system prompt, tool declarations, and
 * completed-turn history, so the side request reuses the parent's prompt cache.
 * The question card can stay pending while the child answers.
 */

/** One option as presented by the pending question card. */
export interface SideAskOption {
  label: string
  description?: string
}

/** The card state sent with a side question so the answer stays grounded. */
export interface SideAskCard {
  title?: string
  header?: string
  detail?: string
  multiSelect?: boolean
  options?: SideAskOption[]
  selected?: string[]
  notes?: Record<string, string>
  custom?: string
}

/** One completed side-question turn, replayed into the next prompt. */
export interface SideAskTurn {
  question: string
  answer: string
}

/** One side-question request. */
export interface SideAskInput {
  question: string
  /** Every question in the pending batch, not only the visible one. */
  questions?: SideAskCard[]
  /** Index of the question the user is currently looking at. */
  activeIndex?: number
  /** Earlier completed turns for this question, oldest first. */
  thread?: SideAskTurn[]
}

/** One side-question answer returned by the host command. */
export interface SideAnswer {
  kind: string
  text: string
}

/** The subset of the remote-commands service this plugin uses. */
export interface SideAskService {
  ask(sessionId: string, input: SideAskInput, signal?: AbortSignal): Promise<SideAnswer>
}

let service: SideAskService | null = null

/**
 * Install the side-question backend for the mounted client plugin.
 * @param next - the backend, or null when the client plugin unloads.
 */
export function setSideAskService(next: SideAskService | null): void {
  service = next
}

/**
 * Read the installed backend. Used to make each plugin instance release only
 * the bridge it installed: a reload mounts the next instance before the old
 * one's cleanup runs, and an unconditional null would break the live one.
 * @returns the current backend, or null when none is installed.
 */
export function getSideAskService(): SideAskService | null {
  return service
}

/**
 * Ask the model a side question through the host `bc-ask` command.
 * @param sessionId - the conversation session the question card belongs to.
 * @param input - the side question plus the pending card batch's current context.
 * @param signal - aborts the command when the card unmounts.
 * @returns the host command's answer text.
 */
export async function askSide(
  sessionId: string,
  input: SideAskInput,
  signal?: AbortSignal,
): Promise<SideAnswer> {
  if (service === null) throw new Error('旁问后端尚未就绪')
  return service.ask(sessionId, input, signal)
}
